```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        // One permitted fetch. Transport failures come back as Err and count as zero
        // characters; a host outside the allowlist traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {} fetched {} chars", now.seconds, fetched);
        let accepted = notifier::notify(&message);

        // The contract requires notified == true on every output. If the channel
        // refuses the notification, trap rather than emit an output that violates it.
        if !accepted {
            panic!("notifier refused the heartbeat; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: accepted,
        }
    }
}

export!(Node);
```

I did not add the `last-input` write to the shared store. This node's `with` clause is its entire authority, and it grants only `http-client`, `notifier`, and `wall-clock`. Recording the input requires a `state-rw` import, which that clause does not include. Adding it would give the node authority the contract does not grant, even with the platform team's approval. The fix belongs in the `with` clause, not the body.

